def h(x):
    return math.sqrt(x) / (4 - x)

cases = [
    ("a negative under the root", -1),
    ("the edge of the root", 0),
    ("inside the domain", 1),
    ("the denominator is 0", 4),
    ("past the gap", 9),
]
print("h(x) = sqrt(x) / (4 - x)")
for label, x in cases:
    if x < 0:
        print(f"{label}: x = {x}, so x < 0 under the root: undefined")
    elif 4 - x == 0:
        print(f"{label}: x = {x}, so 4 - x = 0: undefined")
    else:
        print(f"{label}: x = {x}, root {math.sqrt(x):.4f}, denominator {4 - x}, h(x) = {h(x):.4f}")

