from fractions import Fraction

def check(f, x, y):
    print(f"  check: x = {x} gives {f(x)}, the target {y}: {f(x) == y}")

for target in [5, 2, 0, -1]:
    y = Fraction(target)
    print(f"Is {y} in the range of 1/x?")
    if y == 0:
        print("  no: 1/x = 0 has no solution, since 1 is never 0 times x")
    else:
        print(f"  yes: x = 1/y = {1 / y}")
        check(lambda x: 1 / x, 1 / y, y)
    print(f"Is {y} in the range of (2x + 1)/(x - 3)?")
    if y == 2:
        print("  no: solving needs dividing by y - 2 = 0")
    else:
        x = (3 * y + 1) / (y - 2)
        print(f"  yes: x = (3y + 1)/(y - 2) = {x}")
        check(lambda x: (2 * x + 1) / (x - 3), x, y)

