from fractions import Fraction

def check(f, x, y):
    print(f"  check: x = {x} gives {f(x)}, the target {y}: {f(x) == y}")

count = int(input())
for k in range(count):
    y = Fraction(int(input()))
    print(f"Is {y} in the range?")
    if y == 3:
        print("  no: 3 is not in the range")
    else:
        x = (1 + 2 * y) / (3 - y)
        print(f"  yes: x = {x}")
        check(lambda x: (3 * x - 1) / (x + 2), x, y)

