def first_clash(points):
    seen = {}
    for x, y in points:
        if x in seen and seen[x] != y:
            return f"x = {x} has two outputs, {seen[x]} and {y}"
        seen[x] = y
    return ""

cases = [
    ("a parabola's points", [(-2, 2), (-1, -1), (0, -2), (1, -1), (2, 2)]),
    ("a circle's points", [(-2, 0), (1, 1.732), (1, -1.732), (2, 0)]),
    ("a constant", [(0, 3), (1, 3), (2, 3)]),
    ("a repeated pair", [(1, 2), (1, 2), (4, 0)]),
    ("temperatures to days", [(18, 1), (21, 2), (18, 3)]),
]
for label, points in cases:
    clash = first_clash(points)
    if clash == "":
        print(f"{label}: every input has one output, so a function")
    else:
        print(f"{label}: {clash}, so not a function")

